import{_ as e,o as l,c as a,ag as o}from"./chunks/framework.D64lb950.js";const h=JSON.parse('{"title":"《穷查理宝典》读书笔记 - 构建你的思维模型武器库","description":"","frontmatter":{"title":"《穷查理宝典》读书笔记 - 构建你的思维模型武器库","date":"2026-06-24T00:00:00.000Z","tags":["读书笔记","思维模型","投资","终身学习"],"category":"读书笔记"},"headers":[],"relativePath":"posts/poor-charlies-almanack-review.md","filePath":"posts/poor-charlies-almanack-review.md","lastUpdated":null}'),r={name:"posts/poor-charlies-almanack-review.md"};function n(s,t,i,d,p,g){return l(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="《穷查理宝典》读书笔记-构建你的思维模型武器库" tabindex="-1">《穷查理宝典》读书笔记 - 构建你的思维模型武器库 <a class="header-anchor" href="#《穷查理宝典》读书笔记-构建你的思维模型武器库" aria-label="Permalink to &quot;《穷查理宝典》读书笔记 - 构建你的思维模型武器库&quot;">​</a></h1><p>这本书我读了三遍。第一遍觉得是一个聪明老头的碎碎念，第二遍开始意识到那些&quot;碎碎念&quot;背后有一套严密的思维系统，第三遍才真正明白——这本书不是在教你投资，是在教你<strong>如何正确地思考</strong>。</p><p>查理·芒格，伯克希尔·哈撒韦的副董事长，巴菲特 60 年的搭档。但读这本书之前我对他几乎一无所知，毕竟他一直活在巴菲特的光环背后。读完才知道，巴菲特说&quot;是查理让我从猩猩进化成了人&quot;不是谦虚——芒格是那个真正搭建了伯克希尔投资哲学底层逻辑的人。</p><p>这本书不是芒格自己写的，是他的朋友彼得·考夫曼整理的演讲稿、文章和谈话。结构松散，但思想密度极高——<strong>几乎每一页都值得停下来想一会儿</strong>。</p><hr><h2 id="多元思维模型-不要只拿一把锤子" tabindex="-1">多元思维模型：不要只拿一把锤子 <a class="header-anchor" href="#多元思维模型-不要只拿一把锤子" aria-label="Permalink to &quot;多元思维模型：不要只拿一把锤子&quot;">​</a></h2><p>芒格最核心的思想，就藏在他反复念叨的那句话里：</p><blockquote><p>&quot;手里只拿一把锤子的人，看什么都像钉子。&quot;</p></blockquote><p>这句话我最初以为是说专业人士的狭隘，后来发现不对——<strong>他说的是所有人</strong>。每个人都有一把&quot;锤子&quot;，就是自己最擅长或最熟悉的那个领域的思维方式：</p><table tabindex="0"><thead><tr><th style="text-align:left;">你是什么人</th><th style="text-align:left;">你的锤子</th></tr></thead><tbody><tr><td style="text-align:left;">程序员</td><td style="text-align:left;">用代码逻辑解释一切</td></tr><tr><td style="text-align:left;">经济学家</td><td style="text-align:left;">用供需曲线解释一切</td></tr><tr><td style="text-align:left;">心理学家</td><td style="text-align:left;">用童年创伤解释一切</td></tr><tr><td style="text-align:left;">医生</td><td style="text-align:left;">用病理指标解释一切</td></tr></tbody></table><p>而芒格的主张是：<strong>你应该掌握每个重要学科里最核心的两三个模型，然后把它们组合起来用。</strong></p><p>他列出的关键学科和模型大致包括：</p><ul><li><strong>数学</strong>：复利思维、概率论、决策树</li><li><strong>心理学</strong>：误判心理学（他自己总结了 25 种倾向）</li><li><strong>经济学</strong>：规模优势、对比优势</li><li><strong>物理学</strong>：临界质量、反馈回路</li><li><strong>生物学</strong>：自然选择的进化思维</li></ul><p><strong>你不必成为每个领域的专家，但你得知道那个领域里最重要的思考工具是什么。</strong></p><p>🎯 <strong>我是怎么用的</strong></p><ul><li>做技术选型时，不只从工程角度看（代码好不好写），也加一个经济学视角（边际成本会不会越来越高？）</li><li>遇到问题时先问自己：&quot;我是不是在用老本行的套路硬套一个不同性质的问题？&quot;</li><li>刻意去读自己专业以外的书——心理学、生物学、历史——不是兴趣广泛，是<strong>思维模型需要原料</strong></li></ul><hr><h2 id="逆向思维-反过来想-总是反过来想" tabindex="-1">逆向思维：反过来想，总是反过来想 <a class="header-anchor" href="#逆向思维-反过来想-总是反过来想" aria-label="Permalink to &quot;逆向思维：反过来想，总是反过来想&quot;">​</a></h2><p>芒格有一句名言，几乎成了他的人生标签：</p><blockquote><p>&quot;告诉我我会死在哪里，我就永远不去那个地方。&quot;</p></blockquote><p>这就是逆向思维的核心：<strong>与其想&#39;怎么成功&#39;，不如想&#39;怎么失败然后避开&#39;。</strong></p><p>这个思维方式的厉害之处在于——正向思考往往太模糊，&quot;怎么幸福&quot;&quot;怎么赚钱&quot;这种问题你很难给出一个可操作的答案。但反过来问就具体多了：</p><table tabindex="0"><thead><tr><th style="text-align:left;">正向问题（难回答）</th><th style="text-align:left;">逆向问题（可操作）</th></tr></thead><tbody><tr><td style="text-align:left;">怎么才能幸福？</td><td style="text-align:left;">什么会让人不幸福？——嫉妒、抱怨、自怜、不靠谱的伴侣。避开这些</td></tr><tr><td style="text-align:left;">怎么才能赚到钱？</td><td style="text-align:left;">什么会让人破产？——过度杠杆、跟风投机、不承认错误。不做这些</td></tr><tr><td style="text-align:left;">怎么写出好代码？</td><td style="text-align:left;">什么会导致烂代码？——没测试、没文档、不 Code Review。反过来做</td></tr></tbody></table><p>我在用这个方法之后，最明显的变化是——做决策前我会先列一个&quot;不可为清单&quot;。不是因为我有自制力，而是<strong>想清楚了自己要避开什么，选择反而少了，决策反而快了。</strong></p><hr><h2 id="人类误判心理学-你比自己以为的好骗得多" tabindex="-1">人类误判心理学：你比自己以为的好骗得多 <a class="header-anchor" href="#人类误判心理学-你比自己以为的好骗得多" aria-label="Permalink to &quot;人类误判心理学：你比自己以为的好骗得多&quot;">​</a></h2><p>这是全书我读得最慢、划笔记最多的一章。芒格总结出了 25 种让人做出错误判断的心理倾向，每一种都是一记闷棍——<strong>你读完会发现，你以为的理性决策，其实全是这些倾向在背后操纵。</strong></p><p>我挑几个最让我警醒的：</p><h3 id="_1-奖励和惩罚超级反应倾向" tabindex="-1">1. 奖励和惩罚超级反应倾向 <a class="header-anchor" href="#_1-奖励和惩罚超级反应倾向" aria-label="Permalink to &quot;1. 奖励和惩罚超级反应倾向&quot;">​</a></h3><blockquote><p>&quot;永远不要低估激励的力量。&quot;</p></blockquote><p>人会对激励做出反应——而且是<strong>强烈的、有时甚至扭曲的反应</strong>。绩效考核考什么，员工就做什么，哪怕那个指标和真正的价值没什么关系。联邦快递以前按时间付薪，夜班工人效率极低；改成按班次付薪后，效率暴增。</p><p>启示：<strong>永远先看清楚激励机制是什么，再判断一个人的行为。</strong></p><h3 id="_2-喜欢-热爱倾向" tabindex="-1">2. 喜欢/热爱倾向 <a class="header-anchor" href="#_2-喜欢-热爱倾向" aria-label="Permalink to &quot;2. 喜欢/热爱倾向&quot;">​</a></h3><p>我们会因为喜欢一个人而忽略他的错误，也会因为讨厌一个人而否定他的正确。这在投资里是最致命的——你觉得一家公司&quot;酷&quot;、CEO&quot;有魅力&quot;，就开始忽略财务报表上的红色信号。</p><p>启示：<strong>做判断时把人和事拆开。你可以喜欢一个人，但别让喜欢影响判断。</strong></p><h3 id="_3-避免不一致倾向" tabindex="-1">3. 避免不一致倾向 <a class="header-anchor" href="#_3-避免不一致倾向" aria-label="Permalink to &quot;3. 避免不一致倾向&quot;">​</a></h3><p>人一旦公开说过某个观点，几乎就不可能改了——不是因为固执，是因为<strong>大脑把&quot;改变观点&quot;等同于&quot;承认自己之前很蠢&quot;</strong>。这也是为什么成年人几乎不可能在大事上改变立场。</p><p>启示：<strong>别在公开场合轻易表态。保留&#39;我可能错了&#39;的余地。</strong></p><h3 id="_4-自视过高倾向" tabindex="-1">4. 自视过高倾向 <a class="header-anchor" href="#_4-自视过高倾向" aria-label="Permalink to &quot;4. 自视过高倾向&quot;">​</a></h3><p>90% 的司机认为自己的驾驶技术高于平均水平——这在统计上是不可能的。我们在几乎所有方面都高估自己：能力、运气、道德水准。</p><p>启示：<strong>做重大决策前，强迫自己写出三个可能出错的地方。写不出来就是没想清楚。</strong></p><p>完整的 25 种倾向我不逐一罗列了，但这一章的价值在于：<strong>它给了你一个检查清单。每次做完决策，对照着过一遍——我中了哪个倾向？</strong></p><hr><h2 id="能力圈-知道自己不知道什么" tabindex="-1">能力圈：知道自己不知道什么 <a class="header-anchor" href="#能力圈-知道自己不知道什么" aria-label="Permalink to &quot;能力圈：知道自己不知道什么&quot;">​</a></h2><blockquote><p>&quot;知道自己不知道什么，比聪明更重要。&quot;</p></blockquote><p>芒格和巴菲特一辈子都在说这句话。他们的投资策略简单到不可思议：**只投自己真正理解的生意。**不理解的一律不碰——不管多热门、多少人赚了钱。</p><p>这就是能力圈的概念：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>能力圈以内：你真正懂的东西。不是&quot;听说过&quot;、不是&quot;有印象&quot;。</span></span>
<span class="line"><span>能力圈边缘：你大概知道但不确定的东西。可以学习，但别在这里下重注。</span></span>
<span class="line"><span>能力圈以外：你完全不懂的东西。承认自己不懂，果断远离。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>承认自己不懂，是一种被严重低估的能力。</strong></p><p>我做程序员的时候，最怕面试官问到自己不会的技术。后来想通了——大方说&quot;这个我不熟&quot;比硬头皮瞎编强一百倍。芒格一辈子被问到过无数问题，他的标准回答之一是：&quot;我不知道。&quot;然后就不说话了。</p><hr><h2 id="芒格的投资检查清单" tabindex="-1">芒格的投资检查清单 <a class="header-anchor" href="#芒格的投资检查清单" aria-label="Permalink to &quot;芒格的投资检查清单&quot;">​</a></h2><p>这部分我读的时候专门做了笔记，因为它的普适性远超投资领域。芒格做投资决策前会过一遍这个清单：</p><ol><li><strong>风险</strong>：最大的风险是什么？我真的理解这个风险吗？</li><li><strong>能力</strong>：这是我能力圈之内的事吗？</li><li><strong>数据</strong>：有什么事实是我忽略了或者不愿意面对的？</li><li><strong>心理学</strong>：我现在的情绪（贪婪、恐惧、嫉妒）有没有影响判断？</li><li><strong>逆向</strong>：反过来的情况可能是什么？它发生的概率是多少？</li></ol><p>我把这个清单改造成了技术决策版：</p><table tabindex="0"><thead><tr><th style="text-align:left;">芒格原版</th><th style="text-align:left;">技术决策改编</th></tr></thead><tbody><tr><td style="text-align:left;">最大的风险是什么？</td><td style="text-align:left;">这个方案最坏会导致什么后果？</td></tr><tr><td style="text-align:left;">这是我能力圈之内的吗？</td><td style="text-align:left;">我的团队能驾驭这个技术栈吗？</td></tr><tr><td style="text-align:left;">有什么事实被我忽略了？</td><td style="text-align:left;">测试覆盖率、线上监控、回滚方案，都齐全吗？</td></tr><tr><td style="text-align:left;">我的情绪有没有影响？</td><td style="text-align:left;">我选这个方案是因为它&quot;最合适&quot;还是因为&quot;大家都在用&quot;？</td></tr><tr><td style="text-align:left;">反过来的情况可能是什么？</td><td style="text-align:left;">如果我们什么都不做，会怎样？</td></tr></tbody></table><hr><h2 id="终身学习-聪明人没有不每天阅读的" tabindex="-1">终身学习：聪明人没有不每天阅读的 <a class="header-anchor" href="#终身学习-聪明人没有不每天阅读的" aria-label="Permalink to &quot;终身学习：聪明人没有不每天阅读的&quot;">​</a></h2><p>这是全书被引用最多的一句话：</p><blockquote><p>&quot;我这辈子遇到的聪明人，没有一个不每天阅读的——没有，一个都没有。&quot;</p></blockquote><p>芒格自己的阅读量惊人。他被称为&quot;长着两条腿的书架&quot;，80 多岁时依然每天阅读四五个小时。不是因为勤奋——因为<strong>阅读对他来说是获取思维模型最便宜的方式。</strong></p><p>一本书几十块钱，换来的是另一个人穷尽一生思考的精华。<strong>还有什么投资比这个回报率更高？</strong></p><p>更重要的是——不读书的人，只能从自己的经验中学习。而一个人的经验太有限了。你不可能亲自犯所有错误再吸取教训，但从书里你可以看到无数人犯过的错、走过的路。</p><hr><h2 id="诚实、正直与简单的普世智慧" tabindex="-1">诚实、正直与简单的普世智慧 <a class="header-anchor" href="#诚实、正直与简单的普世智慧" aria-label="Permalink to &quot;诚实、正直与简单的普世智慧&quot;">​</a></h2><p>芒格反复强调一个观点：<strong>诚实不是道德选择，是最优策略。</strong></p><p>因为诚实不需要记忆力。你说了谎，就得记住你说了什么谎、对谁说的、在什么情境下说的——这太累了。而说实话，你只需要记住事实本身。从信息存储的角度看，诚实是成本最低的方案。</p><p>他还提到一个&quot;黄金法则&quot;：<strong>只跟那些你愿意互换位置的人做生意。</strong> 如果你不愿意站在对方的角度承担后果，那就说明这个交易本身有问题。</p><hr><h2 id="芒格哲学与七个习惯的内在共鸣" tabindex="-1">芒格哲学与七个习惯的内在共鸣 <a class="header-anchor" href="#芒格哲学与七个习惯的内在共鸣" aria-label="Permalink to &quot;芒格哲学与七个习惯的内在共鸣&quot;">​</a></h2><p>读这本书的时候我强烈地感觉到——<strong>芒格的很多理念和史蒂芬·柯维的&quot;七个习惯&quot;是相通的。</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">芒格理念</th><th style="text-align:left;">对应七个习惯</th></tr></thead><tbody><tr><td style="text-align:left;">逆向思维</td><td style="text-align:left;">以终为始（从终点倒推现在的行动）</td></tr><tr><td style="text-align:left;">能力圈</td><td style="text-align:left;">要事第一（把精力放在你真正能影响的事上）</td></tr><tr><td style="text-align:left;">激励倾向</td><td style="text-align:left;">双赢思维（设计规则让双方利益一致）</td></tr><tr><td style="text-align:left;">终身学习</td><td style="text-align:left;">不断更新（磨刀不误砍柴工）</td></tr></tbody></table><p>这让我确信——<strong>真正重要的智慧在不同的人那里会以不同的语言表达出来，但内核是相通的。</strong></p><hr><h2 id="我的-不可为清单-与思维模型实践" tabindex="-1">我的&quot;不可为清单&quot;与思维模型实践 <a class="header-anchor" href="#我的-不可为清单-与思维模型实践" aria-label="Permalink to &quot;我的&quot;不可为清单&quot;与思维模型实践&quot;">​</a></h2><p>读完这本书之后，我在 Notion 里建了一个页面，叫&quot;不可为清单&quot;。参考芒格的逆向思维：</p><p><strong>投资与财务</strong></p><ul><li>[ ] 不投自己不理解的东西（不管涨了多少）</li><li>[ ] 不加杠杆</li><li>[ ] 不在情绪激动时做财务决策</li></ul><p><strong>工作与技术</strong></p><ul><li>[ ] 不因为&quot;别人都在用&quot;就选一个技术栈</li><li>[ ] 不做没有回滚方案的线上变更</li><li>[ ] 不在没理解需求时就开始写代码</li></ul><p><strong>生活与学习</strong></p><ul><li>[ ] 不连续三天不读书</li><li>[ ] 不在公开场合对不确定的事做绝对表态</li><li>[ ] 不因为一个人&quot;看着顺眼&quot;就忽略他逻辑上的问题</li></ul><p>这个清单我会每季度更新一次。重点不是写得对，是<strong>真的用它。</strong></p><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><p>这个系列的其他几篇：</p><ul><li><a href="/my-blog/posts/thinking-fast-and-slow-review">《思考，快与慢》读书笔记</a> —— 系统1和系统2如何在你不知情时左右你的判断</li><li><a href="/my-blog/posts/seven-habits-review">《高效能人士的七个习惯》读书笔记</a> —— 从依赖到独立到互赖的成长路径</li><li><a href="/my-blog/posts/nonviolent-communication-review">《非暴力沟通》读书笔记</a> —— 沟通中最重要的是你真正想要什么</li><li><a href="/my-blog/posts/deliberate-practice-review">《刻意练习》读书笔记</a> —— 时间只是入场券，练习的方法才是决定因素</li><li><a href="/my-blog/posts/good-books-recommendation">值得反复阅读的几本好书</a> —— 5 本书的简要速览</li></ul><hr><p><strong>最后记住芒格的这句话：</strong></p><blockquote><p>&quot;获得普世智慧很简单，但不容易。简单的是道理，不容易的是你真的去做。&quot;</p></blockquote>`,90)])])}const q=e(r,[["render",n]]);export{h as __pageData,q as default};
